import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"否","description":"周易正義 - 否","frontmatter":{"title":"否","description":"周易正義 - 否"},"headers":[],"relativePath":"classics/zhengyi/012.md","filePath":"classics/zhengyi/012.md"}'),l={name:"classics/zhengyi/012.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>天地否</p></blockquote><blockquote><p>卦辭：否之匪人，不利君子貞，大往小來。</p></blockquote><blockquote><p>彖曰：否，之匪人，不利君子貞。大往小來，則是天地不交而萬物不通也，上下不交而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子，小人道長，君子道消也。</p></blockquote><h1 id="否" tabindex="-1">否 <a class="header-anchor" href="#否" aria-label="Permalink to “否”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“否之匪人”者，言否閉之世，非是人道交通之時，故云“匪人”。“不利君子貞”者，由小人道長，君子道消，故不利君子為正也。陽氣往而陰氣來，故云“大往小來”。陽主生息，故稱“大”；陰主消耗，故稱“小”。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="否之匪人-不利君子貞-大往小來-則是天地不交-而萬物不通也-上下不交-而天下無邦也。內陰而外陽-內柔而外剛-內小人而外君子-小人道長-君子道消也。-​" tabindex="-1">“否之匪人，不利君子貞，大往小來”，則是天地不交，而萬物不通也；上下不交，而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子，小人道長，君子道消也。 ​ <a class="header-anchor" href="#否之匪人-不利君子貞-大往小來-則是天地不交-而萬物不通也-上下不交-而天下無邦也。內陰而外陽-內柔而外剛-內小人而外君子-小人道長-君子道消也。-​" aria-label="Permalink to ““否之匪人，不利君子貞，大往小來”，則是天地不交，而萬物不通也；上下不交，而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子，小人道長，君子道消也。 ​”">​</a></h3><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“上下不交而天下無邦”者，與泰卦反也。《泰卦》雲“上下交而其志同”，此應雲“上下不交則其志不同”也。非但其志不同，上下乖隔，則邦國滅亡，故變雲“天下無邦”也。“內柔而外剛”者，欲取否塞之義，故內至柔弱，外御剛彊，所以否閉。若欲取“通泰”之義，則雲“內健”“外順”。各隨義為文，故此雲“剛柔”，不雲：“健順”。</p><h3 id="《象》曰-天地不交-否。君子以儉德闢難-不可榮以祿。-​" tabindex="-1">《象》曰：天地不交，否。君子以儉德闢難，不可榮以祿。 ​ <a class="header-anchor" href="#《象》曰-天地不交-否。君子以儉德闢難-不可榮以祿。-​" aria-label="Permalink to “《象》曰：天地不交，否。君子以儉德闢難，不可榮以祿。 ​”">​</a></h3><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“君子以儉德闢難”者，言君子於此否塞之時，以節儉為德，闢其危難，不可榮華其身，以居祿位。此若據諸侯公卿言之，闢其群小之難，不可重受官賞；若據王者言之，謂節儉為德，闢其陰陽已運之難，不可重自榮華而驕逸也。</p><h2 id="初六-拔茅茹-以其匯-貞-吉亨。-​" tabindex="-1">初六：拔茅茹，以其匯，貞，吉亨。 ​ <a class="header-anchor" href="#初六-拔茅茹-以其匯-貞-吉亨。-​" aria-label="Permalink to “初六：拔茅茹，以其匯，貞，吉亨。 ​”">​</a></h2><p>王弼：居否之初，處順之始，為類之首者也。順非健也，何可以徵？居否之時，動則入邪，三陰同道，皆不可進。故“茅茹”以類，貞而不諂，則“吉亨”。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“拔茅茹”者，以居否之初，處順之始，未可以動，動則入邪，不敢前進。三陰皆然，猶若拔茅牽連其根相茹也。己若不進，餘皆從之，故云“拔茅茹”也。“以其匯”者，以其同類，共皆如此。“貞吉亨”者，守正而居志在於君，乃得吉而亨通。</p><h3 id="《象》曰-拔茅貞吉-志在君也。-​" tabindex="-1">《象》曰：拔茅貞吉，志在君也。 ​ <a class="header-anchor" href="#《象》曰-拔茅貞吉-志在君也。-​" aria-label="Permalink to “《象》曰：拔茅貞吉，志在君也。 ​”">​</a></h3><p>王弼：志在於君，故不苟進。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“志在君”者，釋“拔茅貞吉”之義。所以居而守正者，以其志意在君，不敢懷諂苟進，故得“吉亨”也。此假外物以明人事。</p><h2 id="六二-包承-小人吉-大人否-亨。-​" tabindex="-1">六二：包承，小人吉，大人否，亨。 ​ <a class="header-anchor" href="#六二-包承-小人吉-大人否-亨。-​" aria-label="Permalink to “六二：包承，小人吉，大人否，亨。 ​”">​</a></h2><p>王弼：居“否”之世，而得其位，用其至順，包承於上，小人路通，內柔外剛，大人“否”之，其道乃“亨”。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“包承”者，居“否”之世而得其位，用其志順，包承於上。“小人吉”者，否閉之時，小人路通，故於小人為吉也。“大人否亨”者，若大人用此“包承”之德，能否閉小人之“吉”，其道乃亨。</p><h3 id="《象》曰-大人否亨-不亂群也。-​" tabindex="-1">《象》曰：“大人否亨”，不亂群也。 ​ <a class="header-anchor" href="#《象》曰-大人否亨-不亂群也。-​" aria-label="Permalink to “《象》曰：“大人否亨”，不亂群也。 ​”">​</a></h3><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：此釋所以大人“否亨”之意，良由否閉小人，防之以得其道，小人雖盛，不敢亂群，故言“不亂群”也。</p><h2 id="六三-包羞。-​" tabindex="-1">六三：包羞。 ​ <a class="header-anchor" href="#六三-包羞。-​" aria-label="Permalink to “六三：包羞。 ​”">​</a></h2><p>王弼：俱用小道以承其上，而但不當，所以“包羞”也。</p><h3 id="《象》曰-包羞-位不當也。-​" tabindex="-1">《象》曰：“包羞”，位不當也。 ​ <a class="header-anchor" href="#《象》曰-包羞-位不當也。-​" aria-label="Permalink to “《象》曰：“包羞”，位不當也。 ​”">​</a></h3><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“包羞”者，言群陰俱用小人之道包承於上，以失位不當，所包承之事，唯羞辱己。</p><h2 id="九四-有命無咎。疇離祉。-​" tabindex="-1">九四：有命無咎。疇離祉。 ​ <a class="header-anchor" href="#九四-有命無咎。疇離祉。-​" aria-label="Permalink to “九四：有命無咎。疇離祉。 ​”">​</a></h2><p>王弼：夫處“否”而不可以有命者，以所應者小人也。有命於小人，則消君子之道者也。今初志在君，處乎窮下，故可以有命無咎而疇麗福也。疇謂初也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“有命無咎”者，九四處否之時，其陰爻皆是小人。若有命於小人，則君子道消也。今初六志在於君，守正不進，處於窮下。今九四有命命之，故“無咎”。“疇離祉”者，疇謂疇匹，謂初六也。離，麗也。麗謂附著也。言九四命初，身既無咎，初既被命，附依祉福，言初六得福也。</p><h3 id="《象》曰-有命無咎-志行也。-​" tabindex="-1">《象》曰：“有命無咎”，志行也。 ​ <a class="header-anchor" href="#《象》曰-有命無咎-志行也。-​" aria-label="Permalink to “《象》曰：“有命無咎”，志行也。 ​”">​</a></h3><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋“有命無咎”之義，所以九四有命，得無咎者，由初六志意得行，守正而應於上，故九四之命得無咎。</p><h2 id="九五-休否-大人吉。其亡其亡-繫於苞桑。-​" tabindex="-1">九五：休否，大人吉。其亡其亡，繫於苞桑。 ​ <a class="header-anchor" href="#九五-休否-大人吉。其亡其亡-繫於苞桑。-​" aria-label="Permalink to “九五：休否，大人吉。其亡其亡，繫於苞桑。 ​”">​</a></h2><p>王弼：居尊得位，能休否道者也。施否於小人，否之休也。唯大人而後能然，故曰“大人吉”也。處君子道消之時，已居尊位，何可以安？故心存將危，乃得固也。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>“九五休否”至“繫於苞桑”。○正義曰：“休否”者，休，美也。謂能行休美之事於否塞之時，能施此否閉之道，遏絕小人，則是“否”之休美者也，故云“休否”。“大人吉”者，唯大人乃能如此而得吉也，若其凡人，則不能。“其亡其亡，繫於苞桑”者，在道消之世，居於尊位而遏小人，必近危難，須恆自戒慎其意，常懼其危亡，言丁寧戒慎如此也。“繫於苞桑”者，苞，本也。凡物繫於桑之苞本則牢固也。若能“其亡其亡”，以自戒慎，則有“繫於苞桑”之固，無傾危也。○注“心存將危”。○正義曰：“心存將危”，解“其亡其亡”之義。身雖安靜，心意常存將有危難，但念“其亡其亡”，乃得固者，即“繫於苞桑”也。必雲“苞桑”者；取會韻之義。又桑之為物，其根眾也。眾，則牢固之義。</p><h3 id="《象》曰-大人之吉-位正當也。-​" tabindex="-1">《象》曰：大人之吉，位正當也。 ​ <a class="header-anchor" href="#《象》曰-大人之吉-位正當也。-​" aria-label="Permalink to “《象》曰：大人之吉，位正當也。 ​”">​</a></h3><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋“大人吉”之義，言九五居尊得位，正所以當遏絕小人得其吉。</p><h2 id="上九-傾否-先否後喜。-​" tabindex="-1">上九：傾否，先否後喜。 ​ <a class="header-anchor" href="#上九-傾否-先否後喜。-​" aria-label="Permalink to “上九：傾否，先否後喜。 ​”">​</a></h2><p>王弼：先傾後通，故“後喜”也。始以傾為“否”，後得通乃喜。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：處否之極，否道已終，此上九能傾毀其否，故曰“傾否”也。“先否後喜”者，否道未傾之時，是“先否”之道；否道巳傾之後，其事得通，故曰“後有喜”也。</p><h3 id="《象》曰-否終則傾-何可長也-​" tabindex="-1">《象》曰：否終則傾，何可長也？ ​ <a class="header-anchor" href="#《象》曰-否終則傾-何可長也-​" aria-label="Permalink to “《象》曰：否終則傾，何可長也？ ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋“傾否”之義。否道巳終，通道將至。故“否”之終極，則傾損其否，何得長久？故云“何可長也”。</p>',54)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
